changeSet.sql:
CREATE TYPE finances.lot_origin AS ENUM ('PURCHASE', 'REINVESTMENT', 'MOVE');
ALTER TABLE finances.stock_lots
    ADD COLUMN origin finances.lot_origin NOT NULL DEFAULT 'PURCHASE';
ALTER TABLE finances.crypto_lots
    ADD COLUMN origin finances.lot_origin NOT NULL DEFAULT 'PURCHASE';
ALTER TABLE finances.fund_contributions
    ADD COLUMN origin finances.lot_origin NOT NULL DEFAULT 'PURCHASE';

rollback.sql:
ALTER TABLE finances.fund_contributions DROP COLUMN origin;
ALTER TABLE finances.crypto_lots DROP COLUMN origin;
ALTER TABLE finances.stock_lots DROP COLUMN origin;
DROP TYPE finances.lot_origin;

changeSet.sql:
CREATE TABLE finances.cash_transfers (
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    external_id UUID NOT NULL DEFAULT gen_random_uuid() UNIQUE,
    origin_wallet_id BIGINT NOT NULL REFERENCES finances.wallets(id) ON DELETE CASCADE,
    destination_wallet_id BIGINT NOT NULL REFERENCES finances.wallets(id) ON DELETE CASCADE,
    transfer_date DATE NOT NULL,
    amount NUMERIC NOT NULL CHECK (amount > 0),
    rate NUMERIC NOT NULL DEFAULT 1 CHECK (rate > 0),
    destination_amount NUMERIC GENERATED ALWAYS AS (amount * rate) STORED,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT cash_transfers_distinct_wallets CHECK (origin_wallet_id <> destination_wallet_id)
);
CREATE INDEX idx_cash_transfers_origin_wallet_id ON finances.cash_transfers (origin_wallet_id);
CREATE INDEX idx_cash_transfers_destination_wallet_id ON finances.cash_transfers (destination_wallet_id);

CREATE TABLE finances.cash_withdrawals (
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    external_id UUID NOT NULL DEFAULT gen_random_uuid() UNIQUE,
    wallet_id BIGINT NOT NULL REFERENCES finances.wallets(id) ON DELETE CASCADE,
    withdrawal_date DATE NOT NULL,
    amount NUMERIC NOT NULL CHECK (amount > 0),
    bank_name TEXT NULL CHECK (char_length(bank_name) <= 60),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX idx_cash_withdrawals_wallet_id ON finances.cash_withdrawals (wallet_id);

ALTER TABLE finances.wallets ADD COLUMN cash_reconciled BOOLEAN NOT NULL DEFAULT TRUE;

rollback.sql:
ALTER TABLE finances.wallets DROP COLUMN cash_reconciled;
DROP TABLE finances.cash_withdrawals;
DROP TABLE finances.cash_transfers;
